AIOH_HELP = [
    "# aiohttp — 15592 عنصراً عربياً",
]

_AIOH_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _aioh_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        if open_paren and word in AIOH_METHODS:
            return "." + AIOH_METHODS[word] + open_paren
        if word in AIOH_PROPS:
            return "." + AIOH_PROPS[word]
        return match.group(0)
    if word in AIOH_CONSTS:
        return AIOH_CONSTS[word]
    if word in AIOH_FUNCS:
        return AIOH_FUNCS[word] + (open_paren or "")
    return match.group(0)


def AIOH_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _AIOH_TOKEN.sub(_aioh_replace, text)
